import React, { useState } from "react";
import { User, Building, Mail, Phone } from "lucide-react";

const InputField = ({
  icon: Icon,
  type = "text",
  placeholder,
  value,
  onChange,
  error,
}) => (
  <div className="relative mb-4">
    <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
      <Icon className="h-5 w-5" style={{ color: "#003865" }} />
    </div>
    <input
      type={type}
      placeholder={placeholder}
      value={value}
      onChange={onChange}
      className={`w-full pl-10 pr-4 py-3 border ${
        error ? "border-red-500" : "border-gray-300"
      } rounded-xl text-gray-800 placeholder-gray-500 focus:outline-none transition-all duration-300`}
      style={{
        backgroundColor: "#d9d9d9",
        borderColor: error ? "#ef4444" : "#d9d9d9",
        focusBorderColor: "#003865",
      }}
      onFocus={(e) => (e.target.style.borderColor = "#003865")}
      onBlur={(e) =>
        (e.target.style.borderColor = error ? "#ef4444" : "#d9d9d9")
      }
    />
    {error && <p className="text-red-500 text-sm mt-1 ml-1">{error}</p>}
  </div>
);

const Button = ({ children, disabled = false, onClick }) => (
  <button
    disabled={disabled}
    onClick={onClick}
    className="w-full text-white font-semibold py-3 px-6 rounded-xl shadow-lg transition-all duration-300 disabled:opacity-50 disabled:cursor-not-allowed hover:shadow-xl transform hover:scale-105"
    style={{
      background: "linear-gradient(135deg, #003865 0%, #ef5b0c 100%)",
    }}
  >
    {children}
  </button>
);

export default function Inscription() {
  const [formData, setFormData] = useState({
    nomEntreprise: "",
    nomRepresentant: "",
    prenomRepresentant: "",
    email: "",
    telephone: "",
  });
  const [errors, setErrors] = useState({});
  const [isLoading, setIsLoading] = useState(false);

  const handleChange = (field) => (e) => {
    setFormData((prev) => ({ ...prev, [field]: e.target.value }));
    if (errors[field]) {
      setErrors((prev) => ({ ...prev, [field]: "" }));
    }
  };

  const validateForm = () => {
    const newErrors = {};
    if (!formData.nomEntreprise.trim())
      newErrors.nomEntreprise = "Le nom de l'entreprise est requis";
    if (!formData.nomRepresentant.trim())
      newErrors.nomRepresentant = "Le nom du représentant est requis";
    if (!formData.prenomRepresentant.trim())
      newErrors.prenomRepresentant = "Le prénom du représentant est requis";

    if (!formData.email.trim()) {
      newErrors.email = "L'email est requis";
    } else if (!/\S+@\S+\.\S+/.test(formData.email)) {
      newErrors.email = "Format d'email invalide";
    }

    if (!formData.telephone.trim()) {
      newErrors.telephone = "Le numéro de téléphone est requis";
    } else if (!/^[0-9+\-\s()]+$/.test(formData.telephone)) {
      newErrors.telephone = "Format de téléphone invalide";
    }

    return newErrors;
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const newErrors = validateForm();
    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      return;
    }
    setIsLoading(true);
    setTimeout(() => {
      setIsLoading(false);
      alert("Inscription réussie !");
    }, 2000);
  };

  return (
    <div
      className="min-h-screen flex items-center justify-center px-4 sm:px-6 lg:px-8"
      style={{ backgroundColor: "#d9d9d9" }}
    >
      <div
        className="fixed inset-0"
        style={{
          background:
            "linear-gradient(135deg, #d9d9d9 0%, #f0f0f0 50%, #d9d9d9 100%)",
        }}
      ></div>

      <div className="relative max-w-lg w-full space-y-8">
        <div
          className="backdrop-blur-lg rounded-2xl shadow-2xl p-6 sm:p-8 border"
          style={{
            backgroundColor: "rgba(255, 255, 255, 0.9)",
            borderColor: "#003865",
          }}
        >
          <div className="text-center mb-8">
            <h2
              className="text-2xl sm:text-3xl font-bold mb-2"
              style={{ color: "#003865" }}
            >
              Inscription Entreprise
            </h2>
            <p className="mt-2 text-sm" style={{ color: "#003865" }}>
              Rejoignez notre plateforme dès aujourd'hui
            </p>
          </div>

          <div className="space-y-4">
            <InputField
              icon={Building}
              placeholder="Nom de l'entreprise"
              value={formData.nomEntreprise}
              onChange={handleChange("nomEntreprise")}
              error={errors.nomEntreprise}
            />

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <InputField
                icon={User}
                placeholder="Nom du représentant"
                value={formData.nomRepresentant}
                onChange={handleChange("nomRepresentant")}
                error={errors.nomRepresentant}
              />
              <InputField
                icon={User}
                placeholder="Prénom du représentant"
                value={formData.prenomRepresentant}
                onChange={handleChange("prenomRepresentant")}
                error={errors.prenomRepresentant}
              />
            </div>

            <InputField
              icon={Mail}
              type="email"
              placeholder="Adresse email"
              value={formData.email}
              onChange={handleChange("email")}
              error={errors.email}
            />

            <InputField
              icon={Phone}
              type="tel"
              placeholder="Numéro de téléphone"
              value={formData.telephone}
              onChange={handleChange("telephone")}
              error={errors.telephone}
            />

            <div className="pt-4">
              <Button disabled={isLoading} onClick={handleSubmit}>
                {isLoading
                  ? "Inscription en cours..."
                  : "Créer le compte entreprise"}
              </Button>
            </div>
          </div>

          <div className="mt-6 text-center">
            <p className="text-sm" style={{ color: "#003865" }}>
              Déjà un compte ?{" "}
              <a
                href="/connexion"
                className="font-medium hover:underline transition-colors"
                style={{ color: "#ef5b0c" }}
              >
                Se connecter
              </a>
            </p>
          </div>

          <div className="mt-4 text-center">
            <p className="text-xs" style={{ color: "#003865" }}>
              En vous inscrivant, vous acceptez nos{" "}
              <a
                href="#"
                className="hover:underline transition-colors"
                style={{ color: "#ef5b0c" }}
              >
                conditions d'utilisation
              </a>{" "}
              et notre{" "}
              <a
                href="#"
                className="hover:underline transition-colors"
                style={{ color: "#ef5b0c" }}
              >
                politique de confidentialité
              </a>
            </p>
          </div>
        </div>
      </div>
    </div>
  );
}
